/* ────────────────────────────────────────────────────────────────────── */
/* FadeIn — pure opacity, 1.2s, no translate/slide/bounce                */
/* ────────────────────────────────────────────────────────────────────── */
function useInView(threshold = 0.15) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setInView(true);
          observer.unobserve(el);
        }
      },
      { threshold }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [threshold]);

  return [ref, inView];
}

function FadeIn({ children, delay = 0, className = "" }) {
  const [ref, inView] = useInView();
  return (
    <div
      ref={ref}
      className={className}
      style={{
        opacity: inView ? 1 : 0,
        transition: `opacity 1200ms ease-out ${delay}ms`,
      }}
    >
      {children}
    </div>
  );
}

/* ────────────────────────────────────────────────────────────────────── */
/* Ghost button — transparent, 1px border, uppercase, wide tracking       */
/* Gold appears only on hover, as an outline/text shift — never a fill    */
/* ────────────────────────────────────────────────────────────────────── */
function GhostButton({ children, onClick, className = "", dark = false, disabled = false }) {
  const [hover, setHover] = useState(false);
  const base = dark ? PAPER : INK;
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      className={`inline-flex items-center gap-3 px-9 py-4 text-xs uppercase tracking-[0.25em] transition-colors duration-300 ${disabled ? "opacity-50 cursor-not-allowed" : ""} ${className}`}
      style={{
        fontFamily: FONT_BODY,
        fontWeight: 500,
        background: "transparent",
        border: `1px solid ${hover && !disabled ? ACCENT : base}`,
        color: hover && !disabled ? ACCENT : base,
      }}
    >
      {children}
    </button>
  );
}

/* ────────────────────────────────────────────────────────────────────── */
