/* ────────────────────────────────────────────────────────────────────── */
/* App                                                                      */
/* ────────────────────────────────────────────────────────────────────── */
/* ────────────────────────────────────────────────────────────────────── */
/* Custom cursor — a small shuttlecock glides after the mouse with a      */
/* touch of lag (spring-like, via rAF lerp) and rotates cork-first to     */
/* face the direction of travel, like a real shuttle in flight. Grows and */
/* turns gold over anything clickable. Desktop/mouse only — untouched on  */
/* touch devices, and the native cursor is restored over text fields so   */
/* typing still feels normal.                                             */
/* ────────────────────────────────────────────────────────────────────── */
function ShuttleCursor({ active = true }) {
  const elRef = useRef(null);
  const pos = useRef({ x: -100, y: -100 });
  const target = useRef({ x: -100, y: -100 });
  const angle = useRef(90);
  const [visible, setVisible] = useState(false);
  const [hoveringLink, setHoveringLink] = useState(false);
  const [hoveringText, setHoveringText] = useState(false);
  const [isTouch, setIsTouch] = useState(true);

  useEffect(() => {
    setIsTouch(window.matchMedia("(pointer: coarse)").matches);
  }, []);

  useEffect(() => {
    if (isTouch) return;

    const textTags = ["input", "textarea", "select"];

    const onMove = (e) => {
      target.current = { x: e.clientX, y: e.clientY };
      setVisible(true);
      const el = e.target.closest && e.target.closest("a, button, input, textarea, select, [role='button']");
      const tag = el && el.tagName.toLowerCase();
      setHoveringText(!!el && textTags.includes(tag));
      setHoveringLink(!!el && !textTags.includes(tag));
    };
    const onLeaveWindow = (e) => {
      // relatedTarget is null only when the pointer truly leaves the
      // browser viewport (e.g. off the top/edge of the window) — unlike
      // "mouseleave" on documentElement, this doesn't false-trigger when
      // a modal or other element mounts directly under the cursor.
      if (!e.relatedTarget) setVisible(false);
    };

    window.addEventListener("mousemove", onMove);
    document.addEventListener("mouseout", onLeaveWindow);

    let raf;
    const tick = () => {
      const dx = target.current.x - pos.current.x;
      const dy = target.current.y - pos.current.y;
      pos.current.x += dx * 0.45;
      pos.current.y += dy * 0.45;

      if (Math.hypot(dx, dy) > 0.6) {
        angle.current = Math.atan2(dy, dx) * (180 / Math.PI) - 90;
      }

      if (elRef.current) {
        elRef.current.style.transform =
          `translate(${pos.current.x}px, ${pos.current.y}px) translate(-50%, -50%) rotate(${angle.current}deg)`;
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);

    return () => {
      window.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseout", onLeaveWindow);
      cancelAnimationFrame(raf);
    };
  }, [isTouch]);

  if (isTouch) return null;

  const size = hoveringLink ? 34 : 24;

  return (
    <div
      ref={elRef}
      className="fixed top-0 left-0 z-[9999] pointer-events-none"
      style={{
        opacity: active && visible && !hoveringText ? 1 : 0,
        transition: "opacity 250ms ease",
        width: size,
        height: size,
      }}
    >
      <svg viewBox="0 0 24 24" width="100%" height="100%" style={{ transition: "width 200ms ease, height 200ms ease" }}>
        <path
          d="M12 2 L6.5 13 L17.5 13 Z"
          fill="none"
          stroke={hoveringLink ? ACCENT : INK}
          strokeWidth="1.1"
          strokeLinejoin="round"
          opacity={hoveringLink ? 0.9 : 0.7}
          style={{ transition: "stroke 200ms ease" }}
        />
        <line x1="12" y1="2" x2="12" y2="13" stroke={hoveringLink ? ACCENT : INK} strokeWidth="0.6" opacity="0.45" />
        <circle cx="12" cy="15.6" r="2.5" fill={ACCENT} opacity={hoveringLink ? 1 : 0.85} />
      </svg>
    </div>
  );
}

