export default function App() {
  const [modalOpen, setModalOpen] = useState(false);
  const [presetTier, setPresetTier] = useState(null);
  const [termsAccepted, setTermsAccepted] = useState(null); // null = undecided, true = agreed, false = declined

  const openModal = useCallback((tier) => {
    setPresetTier(tier || null);
    setModalOpen(true);
  }, []);

  const closeModal = useCallback(() => setModalOpen(false), []);

  useEffect(() => {
    document.body.classList.toggle("modal-open", modalOpen || termsAccepted !== true);
    return () => document.body.classList.remove("modal-open");
  }, [modalOpen, termsAccepted]);

  useEffect(() => {
    const links = [
      { rel: "preconnect", href: "https://fonts.googleapis.com" },
      { rel: "preconnect", href: "https://fonts.gstatic.com", crossOrigin: "anonymous" },
    ];
    const created = links.map((l) => {
      const el = document.createElement("link");
      el.rel = l.rel;
      el.href = l.href;
      if (l.crossOrigin) el.crossOrigin = l.crossOrigin;
      document.head.appendChild(el);
      return el;
    });
    return () => created.forEach((el) => el.remove());
  }, []);

  useEffect(() => {
    let favicon = document.querySelector("link[rel='icon']");
    const created = !favicon;
    if (!favicon) {
      favicon = document.createElement("link");
      favicon.rel = "icon";
      document.head.appendChild(favicon);
    }
    favicon.type = "image/png";
    favicon.href = FAVICON_IMAGE;
    return () => {
      if (created) favicon.remove();
    };
  }, []);

  return (
    <div className="bg-white min-h-screen relative">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;800;900&family=Inter:wght@300;400;500;600&display=swap');
        html { scroll-behavior: smooth; }
        @keyframes shapeFloat {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(15px); }
        }
        ::selection { background: #C5A059; color: #0A0A0A; }
        * { border-radius: 0 !important; }
        a:focus-visible, button:focus-visible, input:focus-visible, select:focus-visible {
          outline: 1px solid #C5A059;
          outline-offset: 3px;
        }
        @media (pointer: fine) {
          body:not(.modal-open) * { cursor: none !important; }
          input, textarea, select { cursor: text !important; }
        }
      `}</style>

      {termsAccepted !== true ? (
        termsAccepted === false ? (
          <TermsDeclinedScreen onReview={() => setTermsAccepted(null)} />
        ) : (
          <TermsGateModal
            onAgree={() => setTermsAccepted(true)}
            onDecline={() => setTermsAccepted(false)}
          />
        )
      ) : (
        <>
          {/* Subtle print-grade grain — barely perceptible, adds tactile depth */}
          <svg className="fixed inset-0 w-full h-full pointer-events-none z-[1]" style={{ opacity: 0.025, mixBlendMode: "multiply" }}>
            <filter id="grain">
              <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves="2" stitchTiles="stitch" />
            </filter>
            <rect width="100%" height="100%" filter="url(#grain)" />
          </svg>

          <Nav onOpenModal={() => openModal(null)} />
          <GeometricHero onOpenModal={() => openModal(null)} />
          <StatsBar />
          <Philosophy />
          <Memberships onOpenModal={openModal} />
          <Testimonials />
          <Footer onOpenModal={openModal} />

          <RegistrationModal open={modalOpen} onClose={closeModal} presetTier={presetTier} />

          <ShuttleCursor active={!modalOpen} />
        </>
      )}
    </div>
  );
}
